class ResearchMode(str, Enum):
    SIMA = "sima"
    KUTATAS = "kutatas"

class JobStatus(str, Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED = "cancelled"

class QueryRequest(BaseModel):
    mode: ResearchMode
    prompt: str
    timelimitminutes: int = Field(default=10, ge=1, le=60)
    maxsources: int = Field(default=100, ge=10, le=500)
    excludedomains: List[str] = Field(default_factory=list)
    preferrecent: bool = True
    category: Optional[str] = None

    @validator("prompt")
    def validate_prompt(cls, v: str) -> str:
        if not v or not v.strip():
            raise ValueError("prompt cannot be empty")
