class PersistentJobStore:
    def __init__(self, cache_dir: str = "cache"):
        self.cache_dir = Path(cache_dir)
        self.cache_dir.mkdir(exist_ok=True, parents=True)
        self.jobs_file = self.cache_dir / "jobs.json"
        self._load_jobs()

    def _load_jobs(self) -> None:
        global jobsdb
        if self.jobs_file.exists():
            try:
                with open(self.jobs_file, "r", encoding="utf-8") as f:
                    data = json.load(f)
                loaded = 0
                for jobid, jobdata in data.items():
                    try:
                        jobsdb[jobid] = JobState(**jobdata)
                        loaded += 1
                    except Exception as e:
                        logger.error(f"Failed to parse job {jobid}: {e}")
                logger.info(f"Loaded {loaded} jobs from persistent storage")
            except Exception as e:
                logger.error(f"Failed to load jobs: {e}")

    def save_job(self, job: JobState) -> None:
        global jobsdb
        jobsdb[job.jobid] = job
        self.persist()

    def persist(self) -> None:
        try:
            data = {jobid: job.dict() for jobid, job in jobsdb.items()}
            with open(self.jobs_file, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
        except Exception as e:
            logger.error(f"Failed to persist jobs: {e}")

class ConnectionManager:
    def __init__(self) -> None:
        self.active_connections: Dict[str, List[WebSocket]] = {}

    async def connect(self, jobid: str, websocket: WebSocket) -> None:
        await websocket.accept()
        if jobid not in self.active_connections:
            self.active_connections[jobid] = []
        self.active_connections[jobid].append(websocket)
        logger.info(f"WebSocket connected for job {jobid}")

    def disconnect(self, jobid: str, websocket: WebSocket) -> None:
        if jobid in self.active_connections:
            if websocket in self.active_connections[jobid]:
                self.active_connections[jobid].remove(websocket)
            if not self.active_connections[jobid]:
                del self.active_connections[jobid]
            logger.info(f"WebSocket disconnected for job {jobid}")

    async def broadcast(self, jobid: str, message: Dict[str, Any]) -> None:
        if jobid in self.active_connections:
            disconnected: List[WebSocket] = []
            for connection in list(self.active_connections[jobid]):
                try:
                    await connection.send_json(message)
                except Exception as e:
                    logger.error(f"Broadcast error: {e}")
                    disconnected.append(connection)
            for conn in disconnected:
                self.disconnect(jobid, conn)

class ExaAdapter:
    def __init__(self) -> None:
        apikey = os.environ.get("EXAAPIKEY")
        if not apikey:
            raise ValueError("EXAAPIKEY not found")
        self.client = Exa(apikey=apikey)
        logger.info("Exa client initialized")

    async def search(self, query: str, numresults: int = 50, useautoprompt: bool = True, category: Optional[str] = None, excludedomains: Optional[List[str]] = None) -> Dict[str, Any]:
        try:
            params: Dict[str, Any] = {"query": query, "numresults": min(max(1, numresults), 100), "type": "neural", "text": True, "highlights": True}
            if excludedomains:
                params["excludedomains"] = excludedomains
            if category:
                params["category"] = category
            results = await asyncio.get_event_loop().run_in_executor(None, lambda: self.client.searchandcontents(**params))
            sources: List[Dict[str, Any]] = []
            for result in results.results:
                url = getattr(result, "url", "")
                title = getattr(result, "title", "") or "Untitled"
                text = getattr(result, "text", "") or ""
                highlights = getattr(result, "highlights", None)
                published = getattr(result, "publisheddate", None)
                author = getattr(result, "author", None)
                score = getattr(result, "score", 0.0)
                excerpt = text[:800] if text else (" ".join(highlights)[:800] if isinstance(highlights, list) and highlights else "")
                sources.append({"url": url, "title": title, "date": published, "author": author, "score": float(score) if score is not None else 0.0, "excerpt": excerpt})
            logger.info(f"Exa search completed ({len(sources)} results) for query: {query[:120]}")
            return {"sources": sources, "query": query}
        except Exception as e:
            logger.error(f"Exa search error: {e}")
            raise

class CerebrasAdapter:
    def __init__(self) -> None:
        apikey = os.environ.get("CEREBRASAPIKEY")
        if not apikey:
            raise ValueError("CEREBRASAPIKEY not found")
        self.client = Cerebras(apikey=apikey)
        logger.info("Cerebras client initialized")

    async def generate_synthesis(self, prompt: str, model: str = "gpt-oss-120b", maxtokens: int = 4000) -> str:
        try:
            def call() -> Any:
                return self.client.chat.completions.create(model=model, messages=[{"role": "system", "content": "Te egy kiváló kutatási szintézis-készítő vagy. Pontos, hivatkozásokkal alátámasztott, objektív válaszokat adsz."}, {"role": "user", "content": prompt}], temperature=0.3, max_tokens=maxtokens)
            response = await asyncio.get_event_loop().run_in_executor(None, call)
            result = response.choices[0].message.content or ""
            logger.info(f"Cerebras synthesis generated {len(result)} chars with model {model}")
            return result
        except Exception as e:
            logger.error(f"Cerebras generation error: {e}")
            raise

    async def deep_reasoning(self, question: str, context: str, model: str = "qwen-3-235b-a22b-thinking-2507") -> Dict[str, Any]:
        try:
            prompt = "Végezzen mély érvelést és hipotézis-kidolgozást a következő kérdésre.\nKérdés: " + question + "\nKontextus és források:\n" + context + "\nFeladatok:\n1. Bontsa le a kérdést al-kérdésekre\n2. Állítson fel hipotéziseket és ellenhipotéziseket\n3. Értékelje a bizonyítékokat\n4. Következtessen lépésről-lépésre\n5. Jelölje a bizonytalanságokat\nFormátum: JSON"
            def call() -> Any:
                return self.client.chat.completions.create(model=model, messages=[{"role": "system", "content": "Te egy mély érvelésre specializálódott AI vagy. Gondolkodási folyamatodat lépésről-lépésre dokumentálod."}, {"role": "user", "content": prompt}], temperature=0.4, max_tokens=3000)
            response = await asyncio.get_event_loop().run_in_executor(None, call)
            txt = response.choices[0].message.content or ""
            try:
                start = txt.find("{")
                end = txt.rfind("}")
                if start != -1 and end > start:
                    data = json.loads(txt[start:end + 1])
                else:
                    data = {"questionbreakdown": [], "hypotheses": [], "reasoningchain": txt, "conclusions": [], "uncertainties": []}
            except json.JSONDecodeError:
                data = {"questionbreakdown": [], "hypotheses": [], "reasoningchain": txt, "conclusions": [], "uncertainties": []}
            logger.info(f"Deep reasoning completed with model {model}")
            return data
        except Exception as e:
            logger.error(f"Deep reasoning error: {e}")
            raise

