            def call() -> Any:
                return self.client.chat.completions.create(model="grok-4-fast-non-reasoning", messages=[{"role": "system", "content": "Te egy gyors tény-ellenőrző asszisztens vagy."}, {"role": "user", "content": prompt}], temperature=0.2, max_tokens=500)
