class ResearchOrchestrator:
    def __init__(self) -> None:
        self.exa = ExaAdapter()
        self.cerebras = CerebrasAdapter()
        self.grok = GrokAdapter()

    async def update_and_broadcast(self, job: JobState, progress: Optional[float] = None, current_step: Optional[str] = None, status: Optional[JobStatus] = None) -> None:
        if progress is not None:
            job.progress = max(0.0, min(1.0, progress))
        if current_step is not None:
            job.current_step = current_step
        if status is not None:
            job.status = status
        job.updated_at = datetime.now().isoformat()
        jobstore.save_job(job)
        await wsmanager.broadcast(job.jobid, {"type": "status_update", "jobid": job.jobid, "status": job.status.value, "progress": job.progress, "current_step": job.current_step, "action_logs_count": len(job.action_logs), "sources_count": len(job.sources)})

    async def execute_simple_mode(self, job: JobState) -> None:
        try:
            await self.update_and_broadcast(job, progress=0.05, current_step="Kezdeti keresés Exa-val", status=JobStatus.RUNNING)
            log1 = ActionLog(timestamp=datetime.now().isoformat(), tool="Exa", action="Széles körű webes keresés", parameters={"query": job.prompt, "numresults": job.maxsources, "excludedomains": job.excludedomains, "category": job.category}, result_summary="Keresés indítva", confidence=None)
            job.action_logs.append(log1)
            search = await self.exa.search(query=job.prompt, numresults=job.maxsources, category=job.category, excludedomains=job.excludedomains)
            srcs: List[Source] = []
            for s in search["sources"]:
                score = float(s.get("score") or 0.0)
                reliability = "high" if score >= 0.7 else ("medium" if score >= 0.4 else "low")
                authority = max(min(score, 1.0), 0.0)
                srcs.append(Source(url=s["url"], title=s["title"], date=s.get("date"), author=s.get("author"), score=score, authority_score=authority, reliability=reliability, excerpt=s.get("excerpt") or "", verified=False, id=s.get("id")))
            job.sources = srcs
            log1.result_summary = f"{len(srcs)} forrás találva"
            await self.update_and_broadcast(job, progress=0.4, current_step="Források értékelése")
            tops = srcs[:10]
            context = "\n\n".join([f"Forrás: {s.title}\nURL: {s.url}\nRészlet: {s.excerpt[:800]}" for s in tops])
            await self.update_and_broadcast(job, progress=0.6, current_step="Szintézis generálása (Cerebras)")
            synth_prompt = "Készítsen tömör, jól strukturált választ a következő kérdésre, a megadott források alapján.\nKérdés: " + job.prompt + "\nForrások:\n" + context + "\nKövetelmények: Struktúra (Bevezetés, Érvek, Következtetés), hivatkozás jellegű utalások a forrásokra, tárgyilagos hang."
            synthesis = await self.cerebras.generate_synthesis(prompt=synth_prompt, model="gpt-oss-120b", maxtokens=4000)
            log2 = ActionLog(timestamp=datetime.now().isoformat(), tool="Cerebras GPT-OSS-120B", action="Szintézis generálás", parameters={"maxtokens": 4000, "sourcescount": len(srcs)}, result_summary=f"Válasz {len(synthesis)} karakter", confidence=0.9)
            job.action_logs.append(log2)
            await self.update_and_broadcast(job, progress=0.8, current_step="Gyors ellenőrzés (Grok)")
            claims = [c.strip() for c in synthesis.split("\n") if len(c.strip()) > 20][:5]
            verifications: List[Dict[str, Any]] = []
            for c in claims:
                try:
                    v = await self.grok.quick_verification(c, [s.dict() for s in tops])
                    verifications.append(v)
                except Exception:
                    pass
            verified_count = sum(1 for v in verifications if v.get("verified"))
            avg_conf = round(sum(float(v.get("confidence") or 0.0) for v in verifications) / max(len(verifications), 1), 2)
            log3 = ActionLog(timestamp=datetime.now().isoformat(), tool="xAI Grok 4", action="Állítások ellenőrzése", parameters={"claims_checked": len(verifications)}, result_summary=f"{verified_count}/{len(verifications)} állítás megerősítve, átlag bizalom {avg_conf}", confidence=0.88)
            job.action_logs.append(log3)
            report = "Kutatási Jelentés – Sima Mód\nKérdés: " + job.prompt + "\nForrások száma: " + str(len(srcs)) + "\nIdőpont: " + datetime.now().strftime("%Y-%m-%d %H:%M") + "\n\n" + synthesis + "\n\nEllenőrzési összegzés: " + f"{verified_count}/{len(verifications)} megerősített, átlag bizalom {avg_conf}\nTop 10 forrás:\n" + "\n".join([f"{i+1}. {s.title} — {s.url}" + (f" — {s.date}" if s.date else "") for i, s in enumerate(tops)])
            job.report = report
            job.status = JobStatus.COMPLETED
            await self.update_and_broadcast(job, progress=1.0, current_step="Befejezve", status=JobStatus.COMPLETED)
            (reports_dir / f"report_{job.jobid}.md").write_text(report, encoding="utf-8")
            logger.info(f"Simple mode research completed for job {job.jobid}")
        except Exception as e:
            logger.error(f"Simple mode error: {e}\n{traceback.format_exc()}")
            job.status = JobStatus.FAILED
            job.error = str(e)
            job.updated_at = datetime.now().isoformat()
            jobstore.save_job(job)
            await wsmanager.broadcast(job.jobid, {"type": "status_update", "jobid": job.jobid, "status": job.status.value, "progress": job.progress, "current_step": job.current_step, "error": job.error})

    async def execute_research_mode(self, job: JobState) -> None:
        try:
            await self.update_and_broadcast(job, progress=0.05, current_step="Kérdés-dekompozíció", status=JobStatus.RUNNING)
            ctx0 = "Kérdés: " + job.prompt
            reasoning = await self.cerebras.deep_reasoning(question=job.prompt, context=ctx0, model="qwen-3-235b-a22b-thinking-2507")
            log1 = ActionLog(timestamp=datetime.now().isoformat(), tool="Cerebras Qwen-235B Thinking", action="Dekompozíció és hipotézis-alkotás", parameters={"question": job.prompt}, result_summary=f"Alkérdések: {len(reasoning.get('questionbreakdown', []))}, hipotézisek: {len(reasoning.get('hypotheses', []))}", confidence=0.85)
            job.action_logs.append(log1)
            subqs = reasoning.get("questionbreakdown") or []
            if not isinstance(subqs, list) or not subqs:
                subqs = [job.prompt]
            await self.update_and_broadcast(job, progress=0.15, current_step="Párhuzamos keresés")
            all_sources: List[Dict[str, Any]] = []
            max_per_sub = max(10, min(50, job.maxsources // max(1, len(subqs))))
            async def search_one(q: str) -> None:
                try:
                    res = await self.exa.search(query=q, numresults=max_per_sub, category=job.category, excludedomains=job.excludedomains)
                    all_sources.extend(res["sources"])
                except Exception as e:
                    logger.error(f"Search error for sub-question: {e}")
            await asyncio.gather(*[search_one(q) for q in subqs[:5]])
            dedup: Dict[str, Dict[str, Any]] = {}
            for s in all_sources:
                u = s.get("url")
                if not u:
                    continue
                if u not in dedup or (s.get("score") or 0) > (dedup[u].get("score") or 0):
                    dedup[u] = s
            unique_sources = list(dedup.values())[:min(200, job.maxsources)]
            mapped: List[Source] = []
            for s in unique_sources:
                score = float(s.get("score") or 0.0)
                reliability = "high" if score >= 0.7 else ("medium" if score >= 0.4 else "low")
                mapped.append(Source(url=s["url"], title=s["title"], date=s.get("date"), author=s.get("author"), score=score, authority_score=max(min(score, 1.0), 0.0), reliability=reliability, excerpt=s.get("excerpt") or "", verified=False, id=s.get("id")))
            job.sources = mapped
            await self.update_and_broadcast(job, progress=0.5, current_step="Hipotézisek értékelése")
            hypotheses = reasoning.get("hypotheses") or []
            evals: List[Dict[str, Any]] = []
            tops_for_eval = mapped[:20]
            for h in hypotheses[:10]:
                hyp_text = h if isinstance(h, str) else str(h)
                try:
                    v = await self.grok.quick_verification(hyp_text, [s.dict() for s in tops_for_eval])
                    evals.append({"hypothesis": hyp_text, "verified": bool(v.get("verified")), "verification_confidence": float(v.get("confidence") or 0.0), "supporting_sources": v.get("supporting_sources") or [], "summary": v.get("summary") or ""})
                except Exception as e:
                    logger.error(f"Hypothesis evaluation error: {e}")
            verified_cnt = sum(1 for e in evals if e["verified"])
            log2 = ActionLog(timestamp=datetime.now().isoformat(), tool="xAI Grok 4", action="Hipotézisek ellenőrzése", parameters={"hypotheses_count": len(evals)}, result_summary=f"Megerősítve: {verified_cnt}/{len(evals)}", confidence=0.82)
            job.action_logs.append(log2)
            await self.update_and_broadcast(job, progress=0.65, current_step="Alternatív nézőpontok")
            mid_summary = "Főbb hipotézisek:\n" + "\n".join([f"- {e['hypothesis']}" for e in evals[:5]])
            alt_view = await self.grok.alternative_perspective(topic=job.prompt, current_analysis=mid_summary)
            log3 = ActionLog(timestamp=datetime.now().isoformat(), tool="xAI Grok 4", action="Alternatív nézőpont generálás", parameters={"topic": job.prompt}, result_summary=f"Kritikai elemzés {len(alt_view)} karakter", confidence=0.78)
            job.action_logs.append(log3)
            await self.update_and_broadcast(job, progress=0.8, current_step="Végső jelentés szintézis")
            full_ctx_parts: List[str] = []
            full_ctx_parts.append("Eredeti kérdés: " + job.prompt)
            if subqs:
                full_ctx_parts.append("Alkérdések:\n" + "\n".join([f"{i+1}. {q}" for i, q in enumerate(subqs)]))
            if evals:
                full_ctx_parts.append("Hipotézisek értékelése:\n" + "\n".join([f"- {e['hypothesis']} — Megerősítve: {e['verified']} — Bizalom: {e['verification_confidence']:.2f}" for e in evals[:10]]))
            if alt_view:
                full_ctx_parts.append("Alternatív nézőpont:\n" + alt_view)
            full_ctx_parts.append("Források száma: " + str(len(mapped)))
            top_15 = mapped[:15]
            full_ctx_parts.append("Top 15 forrás:\n" + "\n".join([f"{i+1}. {s.title} — {s.url}" for i, s in enumerate(top_15)]))
            full_ctx = "\n\n".join(full_ctx_parts)
            reqs = "Követelmények:\n1. Tartalomjegyzék\n2. Vezetői összefoglaló (1 oldal)\n3. Módszertan\n4. Megállapítások\n5. Bizonyítékok és hivatkozások\n6. Következtetések\n7. Kockázatok és ellentmondások\n8. Mellékletek (forráslista)"
            final_prompt = "Készítsen részletes, többoldalas kutatási jelentést az alábbi információk alapján.\n" + full_ctx + "\n" + reqs + "\nMinimum 5000 karakter, maximum 15000 karakter. Minden állítást támasszon alá forrásokkal."
            final_report_content = await self.cerebras.generate_synthesis(prompt=final_prompt, model="gpt-oss-120b", maxtokens=6500)
            log4 = ActionLog(timestamp=datetime.now().isoformat(), tool="Cerebras GPT-OSS-120B", action="Végső jelentés szintézis", parameters={"totalsources": len(mapped)}, result_summary=f"Jelentés {len(final_report_content)} karakter", confidence=0.92)
            job.action_logs.append(log4)
            report_sections = []
            report_sections.append("KUTATÁSI JELENTÉS – KUTATÁS MÓD")
            report_sections.append("Kérdés: " + job.prompt)
            report_sections.append("Kutatás időtartam: " + str(job.timelimitminutes) + " perc (beállított maximum)")
            report_sections.append("Források száma: " + str(len(mapped)))
            report_sections.append("Időpont: " + datetime.now().strftime("%Y-%m-%d %H:%M"))
            report_sections.append("Alkalmazott eszközök: Exa keresés, Cerebras szintézis és mély érvelés, xAI Grok ellenőrzés és alternatív nézőpontok")
            report_sections.append(final_report_content)
            if subqs:
                report_sections.append("Alkérdések:\n" + "\n".join([f"{i+1}. {q}" for i, q in enumerate(subqs)]))
            if evals:
                hyp_lines = []
                for i, e in enumerate(evals):
                    sumtxt = e.get("summary") or ""
                    hyp_lines.append(f"{i+1}. {e['hypothesis']} — Megerősítve: {e['verified']} — Bizalom: {e['verification_confidence']:.2f}\n{sumtxt[:200]}")
                report_sections.append("Hipotézisek értékelése:\n" + "\n".join(hyp_lines))
            if alt_view:
                report_sections.append("Alternatív nézőpont és kritikai elemzés:\n" + alt_view)
            sorted_by_score = sorted(mapped, key=lambda x: float(x.score or 0.0), reverse=True)[:20]
            src_lines = []
            for i, s in enumerate(sorted_by_score, 1):
                line = f"{i}. {s.title}"
                if s.date:
                    line += f" — {s.date}"
                line += f" — Pontszám: {float(s.score or 0.0):.2f}"
                if s.author:
                    line += f" — Szerző: {s.author}"
                line += f" — {s.url}"
                src_lines.append(line)
            report_sections.append("Források részletes listája (Top 20 megbízhatóság szerint):\n" + "\n".join(src_lines))
            job.report = "\n\n".join(report_sections)
            job.status = JobStatus.COMPLETED
            await self.update_and_broadcast(job, progress=1.0, current_step="Befejezve", status=JobStatus.COMPLETED)
            (reports_dir / f"report_{job.jobid}.md").write_text(job.report or "", encoding="utf-8")
            logger.info(f"Research mode completed for job {job.jobid}")
        except Exception as e:
            logger.error(f"Research mode error: {e}\n{traceback.format_exc()}")
            job.status = JobStatus.FAILED
            job.error = str(e)
            job.updated_at = datetime.now().isoformat()
            jobstore.save_job(job)
            await wsmanager.broadcast(job.jobid, {"type": "status_update", "jobid": job.jobid, "status": job.status.value, "progress": job.progress, "current_step": job.current_step, "error": job.error})

app = FastAPI(title="Autonóm Kutatógép API", version="1.0.0")
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])
app.mount("/static", StaticFiles(directory=str(static_dir)), name="static")
jobstore = PersistentJobStore(str(cache_dir))
wsmanager = ConnectionManager()
orchestrator = ResearchOrchestrator()

@app.post("/query")
async def create_query(request: QueryRequest, background_tasks: BackgroundTasks) -> Dict[str, Any]:
    jobid = hashlib.md5(f"{request.prompt}{time.time()}".encode()).hexdigest()[:16]
    now = datetime.now().isoformat()
    job = JobState(jobid=jobid, status=JobStatus.PENDING, mode=request.mode, prompt=request.prompt, created_at=now, updated_at=now, progress=0.0, current_step="Inicializálás", timelimitminutes=request.timelimitminutes, maxsources=request.maxsources, excludedomains=request.excludedomains, preferrecent=request.preferrecent, category=request.category)
    jobsdb[jobid] = job
    jobstore.save_job(job)
    if request.mode == ResearchMode.SIMA:
        background_tasks.add_task(orchestrator.execute_simple_mode, job)
    else:
        background_tasks.add_task(orchestrator.execute_research_mode, job)
    logger.info(f"Job created {jobid} - Mode: {request.mode.value}")
    return {"jobid": jobid, "status": "created", "mode": request.mode.value}

@app.post("/upload")
async def upload(file: UploadFile = File(...)) -> Dict[str, Any]:
    try:
        fileid = hashlib.md5(f"{file.filename}{time.time()}".encode()).hexdigest()[:16]
        target = uploads_dir / f"{fileid}_{file.filename}"
        content = await file.read()
        target.write_bytes(content)
        logger.info(f"File uploaded {file.filename} - {fileid}")
        return {"fileid": fileid, "filename": file.filename, "size": len(content), "path": str(target)}
    except Exception as e:
        logger.error(f"Upload error: {e}")
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/status/{jobid}")
async def get_status(jobid: str) -> Dict[str, Any]:
    if jobid not in jobsdb:
        raise HTTPException(status_code=404, detail="Job not found")
    job = jobsdb[jobid]
    return {"jobid": job.jobid, "status": job.status.value, "mode": job.mode.value, "progress": job.progress, "current_step": job.current_step, "created_at": job.created_at, "updated_at": job.updated_at, "error": job.error}

@app.get("/log/{jobid}")
async def get_action_log(jobid: str) -> Dict[str, Any]:
    if jobid not in jobsdb:
        raise HTTPException(status_code=404, detail="Job not found")
    job = jobsdb[jobid]
    return {"jobid": job.jobid, "action_logs": [log.dict() for log in job.action_logs]}

@app.get("/sources/{jobid}")
async def get_sources(jobid: str) -> Dict[str, Any]:
    if jobid not in jobsdb:
        raise HTTPException(status_code=404, detail="Job not found")
    job = jobsdb[jobid]
    return {"jobid": job.jobid, "sources_count": len(job.sources), "sources": [src.dict() for src in job.sources]}

@app.get("/report/{jobid}")
async def get_report(jobid: str, format: str = "json") -> Any:
    if jobid not in jobsdb:
        raise HTTPException(status_code=404, detail="Job not found")
    job = jobsdb[jobid]
    if job.status != JobStatus.COMPLETED:
        raise HTTPException(status_code=400, detail="Report not ready yet")
    if format in ("markdown", "md"):
        return JSONResponse(content={"report": job.report, "format": "markdown"})
    return {"jobid": job.jobid, "report": job.report, "sources_count": len(job.sources), "action_logs_count": len(job.action_logs)}

@app.get("/jobs")
async def list_jobs() -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    for job in jobsdb.values():
        p = job.prompt
        out.append({"jobid": job.jobid, "status": job.status.value, "mode": job.mode.value, "prompt": (p[:100] + "..." if len(p) > 100 else p), "created_at": job.created_at, "progress": job.progress})
    return out

@app.websocket("/ws/{jobid}")
async def websocket_endpoint(websocket: WebSocket, jobid: str) -> None:
    await wsmanager.connect(jobid, websocket)
    try:
        while True:
            if jobid in jobsdb:
                job = jobsdb[jobid]
                await websocket.send_json({"type": "status_update", "jobid": job.jobid, "status": job.status.value, "progress": job.progress, "current_step": job.current_step, "action_logs_count": len(job.action_logs), "sources_count": len(job.sources)})
                if job.status in (JobStatus.COMPLETED, JobStatus.FAILED):
                    await websocket.send_json({"type": "final_result", "jobid": job.jobid, "status": job.status.value, "report_available": job.report is not None})
                    break
            await asyncio.sleep(2)
    except WebSocketDisconnect:
        logger.info(f"WebSocket disconnected for job {jobid}")
    finally:
        wsmanager.disconnect(jobid, websocket)

